shell_commands:
cat >> src/orchestration/tools/registry.test.ts <<'EOF'

describe('ToolRegistry.register', () => {
  it('throws naming the tool when registering a static tool whose inputSchema cannot be compiled', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'bad_schema_tool',
          description: 'Declares an unknown JSON Schema type',
          inputSchema: {type: 'object', properties: {when: {type: 'timestamp'}}},
        },
        async () => 'unreachable'
      )
    ).toThrow(/bad_schema_tool/);
  });
});
EOF
timeout 300 npx jest --runTestsByPath src/orchestration/tools/registry.test.ts 2>&1 | tail -25

python3 - <<'EOF'
p='src/orchestration/tools/registry.ts'
s=open(p).read()
s=s.replace("""import {Ajv} from 'ajv';""","""import {Ajv, type ValidateFunction} from 'ajv';""")
s=s.replace("""  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
}""","""  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validate?: ValidateFunction;
}""")
s=s.replace("""    const resolved = this.resolveDefinition(definition);
    this.tools.set(resolved.name, {definitionSource: definition, execute});
  }""","""    const resolved = this.resolveDefinition(definition);
    const validate = typeof definition === 'function' ? undefined : this.compileSchema(resolved);
    this.tools.set(resolved.name, {definitionSource: definition, execute, validate});
  }

  private compileSchema(definition: ToolDefinition): ValidateFunction {
    try {
      return this.ajv.compile(definition.inputSchema);
    } catch (error) {
      const reason = error instanceof Error ? error.message : String(error);
      throw new Error(`Invalid inputSchema for tool ${definition.name}: ${reason}`);
    }
  }""")
s=s.replace("""    const validate = this.ajv.compile(this.resolveDefinition(tool.definitionSource).inputSchema);""","""    const validate = tool.validate ?? this.compileSchema(this.resolveDefinition(tool.definitionSource));""")
open(p,'w').write(s)
EOF
timeout 300 node --experimental-vm-modules node_modules/jest/bin/jest.js --runTestsByPath src/orchestration/tools/registry.test.ts 2>&1 | tail -6
